#include <stdio.h>
#include <stdlib.h>
#include <long.h>

int cmp(const void *a, const void *b) {
    long long *pa = (long long*)a, *pb = (long long*)b;
    if (*pa < *pb) return -1;
    if (*pa > *pb) return 1;
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int x, y;
} Point;

int cmp_x(const void *a, const void *b) {
    return ((Point*)a)->x - ((Point*)b)->x;
}

int cmp_y(const void *a, const void *b) {
    return *(int*)a - *(int*)b;
}

int main() {
    int N, K;
    scanf("%d %d", &N, &K);
    Point pts[N];
    for (int i = 0; i < N; i++) {
        scanf("%d %d", &pts[i].x, &pts[i].y);
    }

    qsort(pts, N, sizeof(Point), cmp_x);

    long long min_area = -1;

    for (int left = 0; left < N; left++) {
        for (int right = left; right < N; right++) {
            int width = pts[right].x - pts[left].x;

            int ys[N], ycount = 0;
            for (int i = left; i <= right; i++) {
                ys[ycount++] = pts[i].y;
            }
            if (ycount < K) continue;

            qsort(ys, ycount, sizeof(int), cmp_y);

            for (int i = 0; i + K - 1 < ycount; i++) {
                int height = ys[i + K - 1] - ys[i];
                long long area = (long long)width * height;
                if (min_area == -1 || area < min_area) {
                    min_area = area;
                }
            }
        }
    }

    printf("%lld\n", min_area);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef long long ll;

typedef struct {
    ll x, y;
} Point;

int cmp_ll(const void *a, const void *b) {
    ll x = *(const ll *)a;
    ll y = *(const ll *)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

int main(void) {
    int N, K;
    if (scanf("%d %d", &N, &K) != 2) return 0;

    Point *p = (Point *)malloc(sizeof(Point) * N);
    ll *xs = (ll *)malloc(sizeof(ll) * N);
    ll *ys = (ll *)malloc(sizeof(ll) * N);

    for (int i = 0; i < N; i++) {
        scanf("%lld %lld", &p[i].x, &p[i].y);
        xs[i] = p[i].x;
        ys[i] = p[i].y;
    }

    qsort(xs, N, sizeof(ll), cmp_ll);
    qsort(ys, N, sizeof(ll), cmp_ll);

    ll ans = (1LL << 62);

    for (int l = 0; l < N; l++) {
        for (int r = l; r < N; r++) {
            ll x1 = xs[l], x2 = xs[r];

            ll *insideY = (ll *)malloc(sizeof(ll) * N);
            int m = 0;

            for (int i = 0; i < N; i++) {
                if (x1 <= p[i].x && p[i].x <= x2) {
                    insideY[m++] = p[i].y;
                }
            }

            if (m >= K) {
                qsort(insideY, m, sizeof(ll), cmp_ll);
                for (int i = 0; i + K - 1 < m; i++) {
                    ll y1 = insideY[i];
                    ll y2 = insideY[i + K - 1];
                    ll area = (x2 - x1) * (y2 - y1);
                    if (area < ans) ans = area;
                }
            }

            free(insideY);
        }
    }

    printf("%lld\n", ans);

    free(p);
    free(xs);
    free(ys);
    return 0;
}

