int main() {
    int N, K;
    cin >> N >> K;
    vector<long long> x(N), y(N);
    for (int i = 0; i < N; i++) cin >> x[i] >> y[i];

    // Get sorted unique x and y coordinates
    vector<long long> xs = x, ys = y;
    sort(xs.begin(), xs.end()); xs.erase(unique(xs.begin(), xs.end()), xs.end());
    sort(ys.begin(), ys.end()); ys.erase(unique(ys.begin(), ys.end()), ys.end());

    long long ans = LLONG_MAX;
    int nx = xs.size(), ny = ys.size();

    for (int li = 0; li < nx; li++) {
        for (int ri = li; ri < nx; ri++) {
            // Collect y-coords of points with xs[li] <= x <= xs[ri]
            vector<long long> yvals;
            for (int p = 0; p < N; p++) {
                if (x[p] >= xs[li] && x[p] <= xs[ri]) {
                    yvals.push_back(y[p]);
                }
            }
            if ((int)yvals.size() < K) continue;
            sort(yvals.begin(), yvals.end());
            // Sliding window of size K
            for (int k = 0; k + K - 1 < (int)yvals.size(); k++) {
                long long height = yvals[k + K - 1] - yvals[k];
                long long width = xs[ri] - xs[li];
                ans = min(ans, width * height);
            }
        }
    }

    cout << ans << endl;
    return 0;
}

