int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, K;
    cin >> N >> K;
    vector<int> x(N), y(N);
    for (int i = 0; i < N; i++) {
        cin >> x[i] >> y[i];
    }

    // Coordinate compression
    vector<int> xs = x, ys = y;
    sort(xs.begin(), xs.end());
    sort(ys.begin(), ys.end());
    xs.erase(unique(xs.begin(), xs.end()), xs.end());
    ys.erase(unique(ys.begin(), ys.end()), ys.end());

    int xn = xs.size(), yn = ys.size();
    vector<vector<int>> grid(xn, vector<int>(yn, 0));

    for (int i = 0; i < N; i++) {
        int xi = lower_bound(xs.begin(), xs.end(), x[i]) - xs.begin();
        int yi = lower_bound(ys.begin(), ys.end(), y[i]) - ys.begin();
        grid[xi][yi]++;
    }

    // 2D prefix sum
    vector<vector<int>> pref(xn + 1, vector<int>(yn + 1, 0));
    for (int i = 0; i < xn; i++) {
        for (int j = 0; j < yn; j++) {
            pref[i + 1][j + 1] = grid[i][j] + pref[i][j + 1] + pref[i + 1][j] - pref[i][j];
        }
    }

    long long ans = LLONG_MAX;

    // Try all left-right boundaries
    for (int l = 0; l < xn; l++) {
        for (int r = l; r < xn; r++) {
            int top = 0;
            // Sliding window on y
            for (int bot = 0; bot < yn; bot++) {
                while (top < yn) {
                    int cnt = pref[r + 1][top + 1] - pref[l][top + 1] - pref[r + 1][top] + pref[l][top];
                    if (cnt >= K) break;
                    top++;
                }
                if (top < yn) {
                    long long area = (long long)(xs[r] - xs[l]) * (ys[top] - ys[bot]);
                    ans = min(ans, area);
                }
                // Move bottom up: if top < bot, reset top
                if (top < bot) top = bot;
            }
        }
    }

    cout << ans << "\n";
    return 0;
}

