int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, K;
    cin >> N >> K;

    vector<long long> x(N), y(N);
    for (int i = 0; i < N; i++) cin >> x[i] >> y[i];

    long long ans = (1LL << 62);

    // Choose left/right boundaries from x-coordinates of points,
    // and bottom/top boundaries from y-coordinates of points.
    // Any optimal rectangle can be shifted until each side touches some point.
    for (int l = 0; l < N; l++) {
        for (int r = 0; r < N; r++) {
            long long xl = min(x[l], x[r]);
            long long xr = max(x[l], x[r]);

            vector<long long> ys;
            for (int i = 0; i < N; i++) {
                if (xl <= x[i] && x[i] <= xr) ys.push_back(y[i]);
            }

            if ((int)ys.size() < K) continue;
            sort(ys.begin(), ys.end());

            for (int i = 0; i + K - 1 < (int)ys.size(); i++) {
                long long area = (xr - xl) * (ys[i + K - 1] - ys[i]);
                ans = min(ans, area);
            }
        }
    }

    cout << ans << '\n';
    return 0;
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int K = sc.nextInt();
        long[] x = new long[N];
        long[] y = new long[N];
        for (int i = 0; i < N; i++) {
            x[i] = sc.nextLong();
            y[i] = sc.nextLong();
        }

        // Sort points by x
        Integer[] idx = new Integer[N];
        for (int i = 0; i < N; i++) idx[i] = i;
        Arrays.sort(idx, (a, b) -> Long.compare(x[a], x[b]));

        long[] sx = new long[N], sy = new long[N];
        for (int i = 0; i < N; i++) {
            sx[i] = x[idx[i]];
            sy[i] = y[idx[i]];
        }

        long minArea = Long.MAX_VALUE;

        // Enumerate left x-boundary index i, right x-boundary index j
        for (int i = 0; i < N; i++) {
            for (int j = i; j < N; j++) {
                // Points with x in [sx[i], sx[j]] are indices i..j (since sorted by x)
                // But there might be points with same x outside this range... no, all points
                // with x in [sx[i], sx[j]] are exactly those with index l where sx[l] >= sx[i] and sx[l] <= sx[j]
                // Since sorted, that's indices from i to j (but i might not be the leftmost with sx[i])
                // Actually we need all points with x between sx[i] and sx[j]
                // Since sorted, find first index with x >= sx[i] and last with x <= sx[j]
                // But we're iterating i and j, so points i..j all have x in [sx[i], sx[j]]
                // However there might be points before i with x == sx[i] - no, i is the leftmost we pick
                // Let me just collect all points with x in [sx[i], sx[j]]

                List<Long> ys = new ArrayList<>();
                for (int k = 0; k < N; k++) {
                    if (sx[k] >= sx[i] && sx[k] <= sx[j]) {
                        ys.add(sy[k]);
                    }
                }

                if (ys.size() < K) continue;

                Collections.sort(ys);

                for (int t = 0; t + K - 1 < ys.size(); t++) {
                    long area = (sx[j] - sx[i]) * (ys.get(t + K - 1) - ys.get(t));
                    minArea = Math.min(minArea, area);
                }
            }
        }

        System.out.println(minArea);
    }
}

import java.util.*;

public class MinRectangleArea {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int K = sc.nextInt();
        int[][] points = new int[N][2];
        for (int i = 0; i < N; i++) {
            points[i][0] = sc.nextInt();
            points[i][1] = sc.nextInt();
        }

        // Sort by x coordinate
        Arrays.sort(points, (a, b) -> Integer.compare(a[0], b[0]));

        long minArea = Long.MAX_VALUE;

        // Sliding over left index
        for (int left = 0; left < N; left++) {
            // We'll gather y values for points with x >= points[left][0]
            List<Integer> yList = new ArrayList<>();
            for (int right = left; right < N; right++) {
                yList.add(points[right][1]);
                if (right - left + 1 >= K) {
                    // Sort the y values we have so far
                    Collections.sort(yList);
                    // Slide over y to find min y-range for K points
                    for (int i = 0; i + K - 1 < yList.size(); i++) {
                        long yRange = yList.get(i + K - 1) - yList.get(i);
                        long xRange = points[right][0] - points[left][0];
                        long area = xRange * yRange;
                        if (area < minArea) {
                            minArea = area;
                        }
                    }
                }
            }
        }

        System.out.println(minArea);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    static class Point {
        long x, y;
        Point(long x, long y) {
            this.x = x;
            this.y = y;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        int N = fs.nextInt();
        int K = fs.nextInt();

        Point[] p = new Point[N];
        long[] xs = new long[N];
        long[] ys = new long[N];

        for (int i = 0; i < N; i++) {
            long x = fs.nextLong();
            long y = fs.nextLong();
            p[i] = new Point(x, y);
            xs[i] = x;
            ys[i] = y;
        }

        long ans = Long.MAX_VALUE;

        // Any optimal rectangle can have its left/right edges on x-coordinates of points
        // and bottom/top edges on y-coordinates of points.
        for (int li = 0; li < N; li++) {
            for (int ri = 0; ri < N; ri++) {
                long left = xs[li];
                long right = xs[ri];
                if (left > right) continue;

                ArrayList<Long> insideY = new ArrayList<>();
                for (int i = 0; i < N; i++) {
                    if (left <= p[i].x && p[i].x <= right) {
                        insideY.add(p[i].y);
                    }
                }

                if (insideY.size() < K) continue;

                Collections.sort(insideY);

                for (int i = 0; i + K - 1 < insideY.size(); i++) {
                    long bottom = insideY.get(i);
                    long top = insideY.get(i + K - 1);
                    long area = (right - left) * (top - bottom);
                    if (area < ans) ans = area;
                }
            }
        }

        System.out.println(ans);
    }
}
